### Python

```python
import sys
import heapq

def solve():
    input = sys.stdin.readline
    n = int(input())
    p = list(map(int, input().split()))
    ans = [0] * n
    heap = []
    # 我们需要购买 n-1 单位氧气
    for i in range(n - 1):
        # 将第 i 个营地加入候选
        # 堆中元素为 (单价, 已购买次数, -编号) ，这样能保证:
        # 1. 单价最低优先
        # 2. 单价相同时已购买次数较少优先
        # 3. 前两者都相同时，编号较大者优先(因为我们取了负号)
        heapq.heappush(heap, (p[i], 0, -i))
        # 取出当前最优营地
        price, cnt, neg_idx = heapq.heappop(heap)
        cnt += 1
        idx = -neg_idx
        ans[idx] = cnt
        # 重新放入堆，供后续选择
        heapq.heappush(heap, (price, cnt, neg_idx))
    print(' '.join(map(str, ans)))

if __name__ == "__main__":
    solve()
```

