#include <iostream>
#include <queue>
#include <vector>
#include <tuple>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    vector<int> ans(n, 0);
    // 自定义比较：价格小优先；价格相同则次数少优先；两者均相同则编号大优先
    auto cmp = [](const tuple<int, int, int>& a, const tuple<int, int, int>& b) {
        if (get<0>(a) != get<0>(b))
            return get<0>(a) > get<0>(b); // 价格更大的优先级更低
        if (get<1>(a) != get<1>(b))
            return get<1>(a) > get<1>(b); // 次数更多的优先级更低
        return get<2>(a) < get<2>(b);     // 编号更小的优先级更低，即编号大优先
    };
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, decltype(cmp)> pq(cmp);

    for (int i = 0; i < n - 1; ++i) {
        pq.emplace(p[i], 0, i);
        auto [price, cnt, idx] = pq.top();
        pq.pop();
        ++cnt;
        ans[idx] = cnt;
        pq.emplace(price, cnt, idx);
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i];
        if (i < n - 1) cout << ' ';
    }
    cout << '\n';

    return 0;
}
